/bin/bash -c "python3 - <<'PY'
from PIL import Image
import numpy as np, colorsys
im=np.array(Image.open('first_frame.png').convert('RGB'))
# make 1 char per 2x2, classify by a more nuanced palette.
def cl(a):
 r,g,b=a
 H,S,V=colorsys.rgb_to_hsv(r/255,g/255,b/255)
 if V<.08: return ' '
 if V<.18: return '.'
 if V<.30: return ':'
 if S<.10: return 'W' if V>.60 else 'w'
 if H<.045 or H>.97:
  return 'R' if V>.45 else ('r' if V>.25 else 'x')
 if H<.10:
  return 'O' if V>.42 else ('o' if V>.24 else 'd')
 if H<.18:
  return 'Y' if V>.45 else 'y'
 if H<.45:
  return 'N' if V>.35 else 'n'
 if H<.65:
  return 'C' if V>.35 else 'c'
 if H<.85:
  return 'B' if V>.35 else 'b'
 return 'P'
for y in range(0,144,2):
 row=''
 for x in range(0,256,2):
  row+=cl(im[y:y+2,x:x+2].reshape(-1,3).mean(0))
 print(f'{y:03d} {row}')
PY"

